        my_x, my_y = 0, 0

    # Simple safe move toward center if possible
    target_x, target_y = my_x, my_y
    if width is not None and height is not None:
        center_x = max(0, min(width - 1, width // 2))
        center_y = max(0, min(height - 1, height // 2))
        if target_x < center_x:
            target_x = target_x + 1
        elif target_x > center_x:
            target_x = target_x - 1
        if target_y < center_y:
            target_y = target_y + 1
        elif target_y > center_y:
            target_y = target_y - 1

    # Compute delta toward target
    dx = 0
    dy = 0
    if target_x > my_x:
        dx = 1
    elif target_x < my_x:
        dx = -1
    if target_y > my_y:
        dy = 1
    elif target_y < my_y:
        dy = -1

    # Sanity: ensure within allowed set
    if dx not in (-1, 0, 1):
        dx = 0
    if dy not in (-1, 0, 1):
        dy = 0

    return [dx, dy]

